}
function M.template(text)
 if type(text)~='string'then return text end
 local direct=stock[text]or stock['/me '..text]
 if direct then return stock[text]and direct or direct:sub(5)end
 if not text:find('\n',1,true)then return text end
 return (text:gsub('[^\n]+',function(line)return stock[line]or line end))
end
return M
